use xiom.io;

type Student = {
  name: Str;
  math: Int;
  science: Int;
  english: Int;
}

fn Student.average(self) -> Float64 {
  let total = math + science + english;
  return total as Float64 / 3.0;
}

fn Student.highest_subject(self) -> Str {
  if math >= science && math >= english {
    return "Math";
  }
  if science >= math && science >= english {
    return "Science";
  }
  return "English";
}

fn main() -> Int {
  let s = Student{ name: "Zara", math: 88, science: 92, english: 85 };
  io.println(s.average().to_str());
  io.println(s.highest_subject().to_str());
  return 0;
}
